public class MissingFormsDemo {
    private static final Logger log = Logger.getLogger(MissingFormsDemo.class.getName());

    public static void main(String[] args) {
        int[] submitted = {4, 3, 2, 7, 8, 2, 3, 1};  // n=8, duplicates present
        log.info("Submitted KYC form numbers: " + Arrays.toString(submitted));

        KycFormReconciler reconciler = new KycFormReconciler();
        List<Integer> missing = reconciler.findMissingForms(submitted);

        log.info("Never-submitted form numbers: " + missing);
    }
}
