package com.bank.kyc;

import java.util.ArrayList;
import java.util.List;

public class KycFormReconciler {

    public List<Integer> findMissingForms(int[] submitted) {
        int i = 0, n = submitted.length;
        // Duplicate-safe cyclic placement: value v → index v-1.
        while (i < n) {
            int target = submitted[i] - 1;
            if (submitted[i] != submitted[target]) {      // compare VALUES, not indices
                int tmp = submitted[i]; submitted[i] = submitted[target]; submitted[target] = tmp;
            } else {
                i++;
            }
        }
        List<Integer> missing = new ArrayList<>();
        for (int idx = 0; idx < n; idx++) {
            if (submitted[idx] != idx + 1) missing.add(idx + 1);
        }
        return missing;
    }
}
